$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$appId=(int)($_GET['id']??0);$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$appId]);if(!$app){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono aplikacji.</div>',$user);}if(!$appAdmins->canManage((int)$user['id'],$appId,'manage_security')){http_response_code(403);Web::page('Brak dostępu','<div class="alert danger">Brak uprawnień do polityk bezpieczeństwa tej aplikacji.</div>',$user);}
$listToJson=static function(string $value,bool $upper=false):?string{$items=array_values(array_unique(array_filter(array_map('trim',preg_split('/[\r\n,;]+/',$value)?:[]))));if($upper)$items=array_map('strtoupper',$items);return$items===[]?null:json_encode($items,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);};$jsonToText=static function(?string $json):string{$v=$json?json_decode($json,true):[];return is_array($v)?implode("\n",array_map('strval',$v)):'';};$message='';
if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$action=(string)($_POST['action']??'save_policy');try{
 if($action==='save_policy'){$before=['app'=>$app,'policy'=>$db->one('SELECT * FROM application_security_policies WHERE application_id=?',[$appId])];$level=max(1,min(3,(int)($_POST['minimum_auth_level']??1)));$risk=max(0,min(100,(int)($_POST['risk_threshold']??100)));$reauth=max(0,(int)($_POST['force_reauth_seconds']??0));if($reauth>0&&$reauth<60)$reauth=60;$ttl=max(0,(int)($_POST['session_ttl_seconds']??0));if($ttl>0)$ttl=max(300,min(2592000,$ttl));$maxSessions=max(0,min(100,(int)($_POST['max_concurrent_sessions']??0)));$hours=trim((string)($_POST['access_hours_json']??''));if($hours!==''){if(!is_array(json_decode($hours,true)))throw new RuntimeException('Nieprawidłowy JSON godzin dostępu.');}else$hours=null;$allowed=$listToJson((string)($_POST['allowed_countries']??''),true);$denied=$listToJson((string)($_POST['denied_countries']??''),true);$allowIp=$listToJson((string)($_POST['ip_allowlist']??''));$denyIp=$listToJson((string)($_POST['ip_denylist']??''));$zones=$listToJson((string)($_POST['network_zones']??''));$db->transaction(function()use($db,$appId,$user,$level,$risk,$reauth,$hours,$allowed,$denied,$allowIp,$denyIp,$zones,$ttl,$maxSessions):void{$db->execute('INSERT INTO application_security_policies(application_id,require_mfa,minimum_auth_level,require_trusted_device,block_new_devices,risk_threshold,allowed_countries_json,denied_countries_json,ip_allowlist_json,ip_denylist_json,network_zones_json,access_hours_json,force_reauth_seconds,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE require_mfa=VALUES(require_mfa),minimum_auth_level=VALUES(minimum_auth_level),require_trusted_device=VALUES(require_trusted_device),block_new_devices=VALUES(block_new_devices),risk_threshold=VALUES(risk_threshold),allowed_countries_json=VALUES(allowed_countries_json),denied_countries_json=VALUES(denied_countries_json),ip_allowlist_json=VALUES(ip_allowlist_json),ip_denylist_json=VALUES(ip_denylist_json),network_zones_json=VALUES(network_zones_json),access_hours_json=VALUES(access_hours_json),force_reauth_seconds=VALUES(force_reauth_seconds),updated_by=VALUES(updated_by)',[$appId,isset($_POST['require_mfa'])?1:0,$level,isset($_POST['require_trusted_device'])?1:0,isset($_POST['block_new_devices'])?1:0,$risk,$allowed,$denied,$allowIp,$denyIp,$zones,$hours,$reauth?:null,(int)$user['id']]);$db->execute('UPDATE applications SET maintenance_mode=?,session_ttl_seconds=?,max_concurrent_sessions=? WHERE id=?',[isset($_POST['maintenance_mode'])?1:0,$ttl?:null,$maxSessions?:null,$appId]);});$app=$db->one('SELECT * FROM applications WHERE id=?',[$appId]);$after=['app'=>$app,'policy'=>$db->one('SELECT * FROM application_security_policies WHERE application_id=?',[$appId])];$audit->write('application.conditional_access.updated','success',(int)$user['id'],null,$appId,null,['before'=>$before,'after'=>$after]);$message='<div class="alert success">Polityka Conditional Access została zapisana.</div>';
 }elseif($action==='add_rule'){$name=trim((string)($_POST['rule_name']??''));$type=(string)($_POST['rule_type']??'attribute');$effect=(string)($_POST['effect']??'allow');$condition=trim((string)($_POST['condition_json']??'{}'));$decoded=json_decode($condition,true);if($name===''||!in_array($type,['group','system_role','attribute','ip','network_zone','country','time','compound'],true)||!in_array($effect,['allow','deny','require_mfa','require_step_up'],true)||!is_array($decoded))throw new RuntimeException('Nieprawidłowa reguła.');$db->execute('INSERT INTO dynamic_access_rules(application_id,name,rule_type,effect,priority,condition_json,enabled,created_by) VALUES(?,?,?,?,?,?,1,?)',[$appId,$name,$type,$effect,(int)($_POST['priority']??100),json_encode($decoded,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),(int)$user['id']]);$audit->write('application.dynamic_rule.created','success',(int)$user['id'],null,$appId,null,['name'=>$name,'type'=>$type,'effect'=>$effect]);$message='<div class="alert success">Reguła została dodana.</div>';
 }elseif($action==='delete_rule'){$ruleId=(int)($_POST['rule_id']??0);$rule=$db->one('SELECT name FROM dynamic_access_rules WHERE id=? AND application_id=?',[$ruleId,$appId]);if($rule){$db->execute('DELETE FROM dynamic_access_rules WHERE id=? AND application_id=?',[$ruleId,$appId]);$audit->write('application.dynamic_rule.deleted','success',(int)$user['id'],null,$appId,null,['rule_id'=>$ruleId,'name'=>$rule['name']]);}}
}catch(Throwable $e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$app=$db->one('SELECT * FROM applications WHERE id=?',[$appId]);$p=$db->one('SELECT * FROM application_security_policies WHERE application_id=?',[$appId])??['require_mfa'=>0,'minimum_auth_level'=>1,'require_trusted_device'=>0,'block_new_devices'=>0,'risk_threshold'=>100,'allowed_countries_json'=>null,'denied_countries_json'=>null,'ip_allowlist_json'=>null,'ip_denylist_json'=>null,'network_zones_json'=>null,'access_hours_json'=>null,'force_reauth_seconds'=>null];$rules='';foreach($db->all('SELECT * FROM dynamic_access_rules WHERE application_id=? ORDER BY priority,id',[$appId])as$r)$rules.='<tr><td>'.Web::e($r['name']).'</td><td>'.Web::e($r['rule_type']).'</td><td>'.Web::e($r['effect']).'</td><td>'.(int)$r['priority'].'</td><td><code>'.Web::e($r['condition_json']).'</code></td><td><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="action" value="delete_rule"><input type="hidden" name="rule_id" value="'.(int)$r['id'].'"><button class="danger">Usuń</button></form></td></tr>';if($rules==='')$rules='<tr><td colspan="6" class="empty">Brak reguł dynamicznych.</td></tr>';
$content='<div class="page-head"><div><h1>Conditional Access — '.Web::e($app['name']).'</h1><p>Polityki są egzekwowane przed wydaniem authorization code i przy refresh tokenie.</p></div><a class="button" href="/admin/applications/'.$appId.'">Wróć</a></div>'.$message.'<section class="card"><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="action" value="save_policy"><div class="checks"><label class="check"><input type="checkbox" name="require_mfa" '.((bool)$p['require_mfa']?'checked':'').'> Wymagaj MFA</label><label class="check"><input type="checkbox" name="require_trusted_device" '.((bool)$p['require_trusted_device']?'checked':'').'> Wymagaj zaufanego urządzenia</label><label class="check"><input type="checkbox" name="block_new_devices" '.((bool)$p['block_new_devices']?'checked':'').'> Blokuj nowe/niezarejestrowane urządzenia</label><label class="check"><input type="checkbox" name="maintenance_mode" '.((bool)$app['maintenance_mode']?'checked':'').'> Maintenance aplikacji</label></div><div class="form-row"><label>Minimalny auth level<select name="minimum_auth_level"><option value="1" '.((int)$p['minimum_auth_level']===1?'selected':'').'>1 — hasło</option><option value="2" '.((int)$p['minimum_auth_level']===2?'selected':'').'>2 — MFA</option><option value="3" '.((int)$p['minimum_auth_level']===3?'selected':'').'>3 — step-up</option></select></label><label>Risk threshold 0–100<input type="number" min="0" max="100" name="risk_threshold" value="'.(int)$p['risk_threshold'].'"></label><label>Force re-auth [s]<input type="number" min="0" name="force_reauth_seconds" value="'.(int)($p['force_reauth_seconds']??0).'"></label></div><div class="form-row"><label>TTL sesji aplikacji [s]<input type="number" min="0" name="session_ttl_seconds" value="'.(int)($app['session_ttl_seconds']??0).'" placeholder="0 = domyślne"></label><label>Maks. równoległych sesji<input type="number" min="0" max="100" name="max_concurrent_sessions" value="'.(int)($app['max_concurrent_sessions']??0).'" placeholder="0 = bez limitu"></label></div><label>Dozwolone kraje ISO2<textarea name="allowed_countries">'.Web::e($jsonToText($p['allowed_countries_json'])).'</textarea></label><label>Zablokowane kraje ISO2<textarea name="denied_countries">'.Web::e($jsonToText($p['denied_countries_json'])).'</textarea></label><label>IP allowlist — CIDR, jeden na linię<textarea name="ip_allowlist">'.Web::e($jsonToText($p['ip_allowlist_json'])).'</textarea></label><label>IP denylist — CIDR<textarea name="ip_denylist">'.Web::e($jsonToText($p['ip_denylist_json'])).'</textarea></label><label>Network zones — dozwolone CIDR<textarea name="network_zones">'.Web::e($jsonToText($p['network_zones_json'])).'</textarea></label><label>Godziny dostępu — JSON<textarea name="access_hours_json" placeholder="{&quot;timezone&quot;:&quot;Europe/Warsaw&quot;,&quot;days&quot;:[1,2,3,4,5],&quot;start&quot;:&quot;08:00&quot;,&quot;end&quot;:&quot;18:00&quot;}">'.Web::e((string)($p['access_hours_json']??'')).'</textarea></label><button class="primary">Zapisz Conditional Access</button></form></section><section class="card"><h2>Reguły dynamiczne / ABAC</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="action" value="add_rule"><div class="form-row"><label>Nazwa<input name="rule_name" required></label><label>Typ<select name="rule_type"><option>attribute</option><option>group</option><option>system_role</option><option>ip</option><option>network_zone</option><option>country</option><option>time</option><option>compound</option></select></label><label>Efekt<select name="effect"><option>allow</option><option>deny</option><option>require_mfa</option><option>require_step_up</option></select></label><label>Priorytet<input type="number" name="priority" value="100"></label></div><label>Condition JSON<textarea name="condition_json" required>{"key":"department","operator":"equal